// Dial only leads with a phone number that have not been called yet
// (blank, 'pending' or 'new' status = ready to call)
const READY = ['', 'pending', 'new'];
return $input.all().filter(i => String(i.json.phone || '').trim() && READY.includes(String(i.json.call_status || '').trim().toLowerCase()));

// Builds the full Vapi call request: the AI sales caller script, FAQ facts,
// objection handling and the structured qualification schema all live here.
const NL = String.fromCharCode(10);
const settings = $('Call Settings').first().json;
const lead = $json;
const firstName = String(lead.first_name || '').trim() || 'there';
let phone = String(lead.phone || '').replace(/[^0-9+]/g, '');
if (!phone.startsWith('+')) phone = '+' + phone;
const leadSource = String(lead.lead_source || '').trim() || 'a list of San Diego homeowners who asked to hear about ways to save on energy';
const agent = settings.agent_name || 'Alex';

const systemPrompt = [
  'You are ' + agent + ', a friendly, professional outbound sales caller for SolarEase Solutions, a residential solar installation company. You are on a phone call with ' + firstName + '.',
  '',
  'STYLE: Warm, confident and concise. Ask one question at a time. Keep each turn to one or two short sentences. Briefly acknowledge every answer (for example: Got it, that helps) before moving on. Never invent facts. Use the first name naturally, not in every sentence.',
  '',
  'COMPANY FACTS (the only facts you may state):',
  '- Company: SolarEase Solutions',
  '- Address: 123 GreenTech Avenue, San Diego, CA 92101',
  '- Operating hours: Monday to Friday, 9:00 AM to 6:00 PM Pacific Time',
  '- Estimated price range: 10,000 to 25,000 US dollars, depending on system size and the site. An exact quote needs a site assessment.',
  '- What we offer: lower utility bills, flexible financing (cash, loan or lease) and expert installation.',
  'If asked something not covered here (warranties, exact savings, tax credits), say a solar consultant will cover it in detail during the follow-up.',
  '',
  'CALL FLOW:',
  '1. Opening: your greeting has already been spoken. After they reply, introduce yourself and give a short pitch: SolarEase helps homeowners lower their electricity bills with solar, offers flexible financing, and handles expert installation from start to finish. Ask if they have a couple of minutes for a few quick questions to see if their home is a good fit.',
  '2. Qualification. Ask these one at a time, in this order, and clarify vague answers:',
  '   a. What type of roof do you have, for example asphalt shingle, tile, metal or flat?',
  '   b. Roughly what has your average monthly electricity bill been over the last three months?',
  '   c. About how large is your home in square feet?',
  '   d. Is someone usually at home during the day, roughly 10 AM to 4 PM?',
  '   e. How many heavy appliances do you run, such as air conditioners, refrigerators or electric heaters?',
  '   f. How many ceiling fans are in regular use?',
  '   g. Who is your current utility provider, and do you happen to know your peak rate?',
  '   h. Are there any trees or nearby buildings that shade your roof?',
  '   i. Would you prefer to pay cash, take a loan, or lease, and what budget do you have in mind?',
  '   If they do not know an answer, say that is fine and move on.',
  '3. Close: if they are interested, explain the next steps: a solar consultant reviews their answers, prepares an estimate and arranges a site assessment. Ask for a preferred day and time for that follow-up and repeat it back to confirm. Tell them a follow-up email is on its way.',
  '4. Finish politely, thank them by first name, then use the end call tool.',
  '',
  'OBJECTION HANDLING:',
  '- Where did you get my number? Apologize for the surprise and answer honestly: your number came from ' + leadSource + '. Offer to remove them from the list. If they want removal, confirm it, thank them and end the call.',
  '- I am busy right now: Say you completely understand and ask when would be a better time for a quick five minute call. Confirm the day and time, thank them and end the call.',
  '- Not interested: Respect it. Offer one short value point, for example that many homeowners lower their monthly bill with little or no upfront cost through a lease or loan, and ask if a quick look would be worthwhile. If they still decline, thank them warmly and end the call. Never push more than once.',
  '- If asked whether you are an AI, say yes, you are the SolarEase AI assistant.',
  '',
  'FAQ: Answer questions about the address, operating hours and pricing directly from COMPANY FACTS, then return to where you left off.'
].join(NL);

const str = (d) => ({ type: 'string', description: d });

const schema = {
  type: 'object',
  properties: {
    outcome: { type: 'string', enum: ['Interested', 'Not Interested', 'Callback Requested', 'No Response/Hang-up'], description: 'Final call outcome. Interested: wants next steps or an estimate. Not Interested: declined or asked to be removed. Callback Requested: asked to be called back at another time. No Response/Hang-up: voicemail, silence, or hung up before a real conversation.' },
    callback_time: str('Preferred day and time for the callback or follow-up exactly as agreed. Empty if none was given.'),
    roof_type: str('Roof type or material, e.g. asphalt shingle, tile, metal, flat.'),
    avg_monthly_bill: str('Average monthly electricity bill over the last 3 months, e.g. $220.'),
    home_size_sqft: str('Approximate home size in square feet, e.g. 2000.'),
    daytime_occupancy: str('Whether someone is typically home during peak sun hours, with any detail.'),
    heavy_appliances_count: str('Number of heavy appliances (ACs, refrigerators, electric heaters, etc.), with breakdown if given.'),
    ceiling_fans_count: str('Number of ceiling fans in regular use.'),
    utility_provider: str('Current electricity utility provider, e.g. SDG&E.'),
    peak_tariff: str('Peak tariff or rate if known, e.g. $0.45/kWh. Empty if unknown.'),
    shading_concerns: str('Shading from trees or adjacent buildings, or None.'),
    preferred_financing: str('Preferred financing: Cash, Loan or Lease.'),
    budget_expectation: str('Budget expectation stated by the lead.')
  },
  required: ['outcome']
};

const payload = {
  phoneNumberId: settings.vapi_phone_number_id,
  customer: { number: phone, name: firstName, email: String(lead.email || ''), externalId: String(lead.row_number) },
  assistant: {
    name: 'SolarEase Sales Caller',
    firstMessage: 'Hi ' + firstName + ', how are you today?',
    firstMessageMode: 'assistant-speaks-first',
    model: {
      provider: 'openai',
      model: 'gpt-5.4-mini',
      temperature: 0.4,
      messages: [{ role: 'system', content: systemPrompt }],
      tools: [{ type: 'endCall' }]
    },
    voice: { provider: 'vapi', voiceId: 'Elliot' },
    transcriber: { provider: 'deepgram', model: 'nova-3', language: 'en' },
    voicemailDetection: { provider: 'vapi' },
    endCallMessage: 'Thanks so much for your time, ' + firstName + '. Have a great day!',
    maxDurationSeconds: 600,
    metadata: { row_number: lead.row_number, email: lead.email || '', first_name: firstName },
    analysisPlan: {
      structuredDataPlan: { enabled: true, schema: schema, timeoutSeconds: 30 }
    },
    serverMessages: ['end-of-call-report'],
    server: { url: settings.results_webhook_url, headers: { 'x-vapi-secret': 'se-' + $workflow.id } }
  }
};

return { json: { ...lead, call_payload: payload } };

const m = $json.body.message || {};
const call = m.call || {};
const customer = call.customer || m.customer || {};
const assistantMeta = (m.assistant && m.assistant.metadata) || (call.assistant && call.assistant.metadata) || {};
const meta = { ...(call.metadata || {}), ...assistantMeta };
const analysis = m.analysis || call.analysis || {};
let sd = analysis.structuredData || {};
if (typeof sd === 'string') { try { sd = JSON.parse(sd); } catch (e) { sd = {}; } }
const reason = String(m.endedReason || call.endedReason || '');
const duration = Math.round(m.durationSeconds || 0);

const VALID = ['Interested', 'Not Interested', 'Callback Requested', 'No Response/Hang-up'];
const NO_ANSWER = ['customer-did-not-answer', 'customer-busy', 'voicemail', 'twilio-failed-to-connect-call', 'customer-did-not-give-microphone-permission'];

let outcome = sd.outcome;
// Safety net: unanswered, voicemail, instant hang-up, or invalid model output -> No Response/Hang-up
if (NO_ANSWER.includes(reason) || duration < 10 || !VALID.includes(outcome)) {
  outcome = 'No Response/Hang-up';
}

const s = (v) => (v === null || v === undefined) ? '' : String(v);

return [{
  json: {
    row_number: Number(meta.row_number || customer.externalId),
    email: s(meta.email || customer.email).trim(),
    first_name: s(meta.first_name || customer.name) || 'there',
    call_status: 'completed',
    outcome,
    callback_time: outcome === 'Callback Requested' || outcome === 'Interested' ? s(sd.callback_time) : '',
    roof_type: s(sd.roof_type),
    avg_monthly_bill: s(sd.avg_monthly_bill),
    home_size_sqft: s(sd.home_size_sqft),
    daytime_occupancy: s(sd.daytime_occupancy),
    heavy_appliances_count: s(sd.heavy_appliances_count),
    ceiling_fans_count: s(sd.ceiling_fans_count),
    utility_provider: s(sd.utility_provider),
    peak_tariff: s(sd.peak_tariff),
    shading_concerns: s(sd.shading_concerns),
    preferred_financing: s(sd.preferred_financing),
    budget_expectation: s(sd.budget_expectation),
    call_summary: s(analysis.summary),
    call_duration: duration,
    ended_reason: reason,
    last_called_at: new Date().toISOString()
  }
}];
